#include <iostream>
#include <string>

std::size_t count_digits(const std::string& input) {
    std::size_t digits = 0;
    for (auto it = input.rbegin(); it != input.rend(); ++it) {
        if (*it == ' ') continue;
        if (*it < '0' || *it > '9') return 0;
        ++digits;
    }
    return digits;
}

int main() {
    const std::string number = "0 59";
    std::cout << number.size() << '\n';
    std::cout << count_digits(number) << '\n';
}
